// Higher-resolution coast distance inferred from the unchanged reference image, quarter-metres.
const bytes=Uint8Array.from(atob(''),c=>c.charCodeAt(0)),grid=new Int16Array(bytes.buffer);
export function referenceCoast(x,z){const u=(x/12600+.5)*768,v=(z/8400+.5)*512;if(u<0||v<0||u>=768||v>=512)return -500;const a=Math.floor(u),b=Math.floor(v),fx=u-a,fz=v-b,i=b*769+a;return ((grid[i]*(1-fx)+grid[i+1]*fx)*(1-fz)+(grid[i+769]*(1-fx)+grid[i+770]*fx)*fz)/4;}
